// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor1, address actor2, uint96 amount) public {
        vm.assume(actor1 != address(0) && actor1 != address(c));
        vm.assume(actor2 != address(0) && actor2 != address(c) && actor2 != actor1);
        uint256 amt = amount == 0 ? 1 : amount;

        vm.deal(actor1, amt);
        vm.prank(actor1);
        c.Put{value: amt}(0);
        assertTrue(c.Acc(actor1).balance == amt, "first Put must credit balance");

        // The lock must be released: any later Put by anyone must succeed.
        vm.deal(actor2, amt);
        vm.prank(actor2);
        bool ok;
        try c.Put{value: amt}(0) { ok = true; } catch { ok = false; }
        assertTrue(ok, "a second Put must succeed because the guard releases the lock");
    }
}

