pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 collectAmt, uint256 warp) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 100 ether);
        collectAmt = bound(collectAmt, 0, 100 ether);
        warp = bound(warp, 1, 365 days);
        vm.warp(block.timestamp + warp);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp);

        // General rule: after any successful Put, a guarded entry (Collect) must not revert;
        // in the correct contract it either collects or silently no-ops.
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        assertTrue(ok, "Collect must not revert after a successful Put (lock must be released)");
    }
}

