contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log));
        amount = bound(amount, 1, 10 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: any successful Put must be logged in the Log contract
