pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log l;

    function setUp() public {
        l = new Log();
        c = new C(address(l));
    }

    function testFuzz_property(uint96 amount, address actor) public {
        vm.assume(actor != address(0) && amount > 0);
        vm.assume(uint256(amount) <= type(uint256).max / 2);

        uint256 before_ = l.HistoryLength();

        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        c.Put{value: uint256(amount)}(0);

        // Every successful deposit must be logged: History grows by exactly one.
        assertTrue(l.HistoryLength() == before_ + 1);
    }
}

