pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", 0));
        assertTrue(ok, "Put should succeed");

        // General rule: every successful Put appends a History entry recording the sender and the exact deposited value.
        (address sender, , uint256 val, ) = log.History(0);
        assertTrue(sender == actor && val == amount, "Put must log the deposit");
    }
}

