pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log theLog;

    function setUp() public {
        theLog = new Log();
        c = new C(address(theLog));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);

        uint256 before = theLog.History().length;

        vm.prank(actor);
        c.Put{value: amount}(0);

        assertEq(theLog.History().length, before + 1, "every successful Put must append exactly one History entry");
    }
}

